@startuml

class ProjectManager {}

class Project {
  + startDate : date
  + endDate : date
  + status : string
  + initiate() : void
  + terminate() : void
}

abstract class WorkProduct {
  + description : string
  + percentComplete : float
  + validate() : void
}

class Requirement extends WorkProduct {
  + validateWithUsers() : void
  + publish(media : string) : void
}

class System extends WorkProduct {
  + validateAgainstRequirements() : void
  + deploy(platform : string) : void
}

class Team {}

ProjectManager "1" -- "1" Team : leads
Team "1" -- "1" Project : executes
Project "1" -- "*" Requirement : uses
Project "1" -- "0..1" System : produces

@enduml

